#include "../../vendor/md4c-reference/src/md4c.c"
static unsigned counts[32];static unsigned char output[8192];static unsigned used;
static int block(MD_BLOCKTYPE t,void*d,void*u){(void)t;(void)d;(void)u;return 0;}
static int span_start(MD_SPANTYPE t,void*d,void*u){(void)d;(void)u;counts[t]++;return 0;}
static int span_end(MD_SPANTYPE t,void*d,void*u){(void)t;(void)d;(void)u;return 0;}
static int text_out(MD_TEXTTYPE t,const MD_CHAR*s,MD_SIZE n,void*u){(void)t;(void)u;memcpy(output+used,s,n);used+=n;return 0;}
int main(void){const char*inputs[]={"[[*target*|label]]","[[`target`|label]]","[[aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa *x*|label]]","[[aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa*x*|label]]","[[target *x*|label]]","[[target ![alt](url)|label]]","[[[link](url)|label]]","[[target|]]","[[|label]]","[[target|*label*]]","[x](url)","[x](url \"title\")","[x](url \"[nested](x)\")","[x](url (title))","[x](url\\))","[*x*](url)","[*x*](url \"title\")","[*x*](url \"[nested](x)\")","[*x*](url (title))","[*x*](url\\))","[[x](y)](url)","[[x](y)](url \"title\")","[[x](y)](url \"[nested](x)\")","[[x](y)](url (title))","[[x](y)](url\\))","[www.example.org](url)","[www.example.org](url \"title\")","[www.example.org](url \"[nested](x)\")","[www.example.org](url (title))","[www.example.org](url\\))","[a@b.com](url)","[a@b.com](url \"title\")","[a@b.com](url \"[nested](x)\")","[a@b.com](url (title))","[a@b.com](url\\))","[<http://e.org>](url)","[<http://e.org>](url \"title\")","[<http://e.org>](url \"[nested](x)\")","[<http://e.org>](url (title))","[<http://e.org>](url\\))","[`x`](url)","[`x`](url \"title\")","[`x`](url \"[nested](x)\")","[`x`](url (title))","[`x`](url\\))","[[www.example.org|label]]","![[www.example.org|label]]","[[a@b.com|label]]","![[a@b.com|label]]","[http://example.org](url)","[[http://example.org|label]]","![[http://example.org|label]]","[www.example.org *tail*](url)","[[www.example.org *tail*|label]]","![[www.example.org *tail*|label]]","[*head* www.example.org](url)","[[*head* www.example.org|label]]","![[*head* www.example.org|label]]","[foo](url`code)tail`","[foo](`url)tail`)","[foo](url[bar)tail](dest)","[foo](url \"ti`tle\")tail`","[foo](url *em)tail*","![foo](url`code)tail`","[foo](<url`code>)tail`","[foo](url \"title [bar\")tail](dest)"};
for(unsigned k=0;k<sizeof(inputs)/sizeof(inputs[0]);k++){memset(counts,0,sizeof(counts));used=0;
 MD_PARSER p={0};p.flags=MD_FLAG_WIKILINKS|MD_FLAG_PERMISSIVEAUTOLINKS;p.enter_block=block;p.leave_block=block;p.enter_span=span_start;p.leave_span=span_end;p.text=text_out;
 int result=md_parse(inputs[k],(MD_SIZE)strlen(inputs[k]),&p,0);printf("[%d,[",result);
 for(int i=0;i<32;i++)printf("%s%u",i?",":"",counts[i]);printf("],\"");
 for(unsigned i=0;i<used;i++)printf("%02x",output[i]);printf("\"]\n");}
return 0;}
